# Translation map for mes lines: old English text -> new Spanish text
# We match the content between mes " and ";
# Format: (original_content, translated_content)

translations = {}

# We'll process line by line and translate mes "..." and select("...") strings
def translate_line(line):
    stripped = line.strip()

    # Handle mes lines
    if stripped.startswith('mes "') and stripped.endswith('";'):
        content = stripped[5:-2]  # Extract between mes " and ";
        translated = translate_mes(content)
        if translated is not None:
            indent = line[:len(line) - len(line.lstrip())]
            return indent + 'mes "' + translated + '";\n'

    # Handle select lines - more complex, can be inside if() or switch()
    if 'select("' in line:
        return translate_select_line(line)

    # Handle mapannounce lines
    if 'mapannounce' in line and '"' in line:
        return translate_mapannounce(line)

    return line

def translate_mes(content):
    """Translate mes content. Returns None if no translation needed."""
    t = mes_translations.get(content)
    if t is not None:
        return t
    return None

def translate_select_line(line):
    """Translate select() options in a line."""
    # Find select("...") pattern
    pattern = r'select\("([^"]*?)"\)'
    match = re.search(pattern, line)
    if match:
        options_str = match.group(1)
        if options_str in select_translations:
            new_options = select_translations[options_str]
            line = line[:match.start()] + 'select("' + new_options + '")' + line[match.end():]
    return line

def translate_mapannounce(line):
    """Translate mapannounce strings."""
    for eng, spa in mapannounce_translations.items():
        if eng in line:
            line = line.replace(eng, spa)
    return line

