# Handle special dynamic mes lines with string concatenation
def process_line(line):
    stripped = line.strip()
    indent = line[:len(line) - len(line.lstrip())]

    # Special dynamic lines with string concatenation
    if 'mes "Your name is ... " + strcharinfo(0) + ". It\'s a very nice name.";' in stripped:
        return indent + 'mes "Tu nombre es ... " + strcharinfo(0) + ". Es un nombre muy bonito.";\n'
    if 'mes "Your name is ... " + strcharinfo(0) + ". It sounds very sagacious.";' in stripped:
        return indent + 'mes "Tu nombre es ... " + strcharinfo(0) + ". Suena muy sagaz.";\n'
    if 'mes "Your name is ... " + strcharinfo(0) + ". Interesting name.";' in stripped:
        return indent + 'mes "Tu nombre es ... " + strcharinfo(0) + ". Nombre interesante.";\n'
    if 'mes "Your name is ... " + strcharinfo(0) + ". It\'s a very nice name.";' in stripped:
        return indent + 'mes "Tu nombre es ... " + strcharinfo(0) + ". Es un nombre muy bonito.";\n'
    if 'mes "Let\'s see, your name is " + strcharinfo(0) + "...";' in stripped:
        return indent + 'mes "Veamos, tu nombre es " + strcharinfo(0) + "...";\n'
    if 'mes "You got " + .@sage_t + " points.";' in stripped:
        return indent + 'mes "Obtuviste " + .@sage_t + " puntos.";\n'
    if 'mes "Welcome, " + strcharinfo(0) + ". I am glad to meet you.";' in stripped:
        return indent + 'mes "Bienvenido, " + strcharinfo(0) + ". Me alegra conocerte.";\n'
    if 'mes "Wrong. " + strcharinfo(0) + ", you got - 10 points.";' in stripped:
        return indent + 'mes "Incorrecto. " + strcharinfo(0) + ", obtuviste - 10 puntos.";\n'
    if 'mes "By the way, " + strcharinfo(0) + ", you just got - 10 points for lying and for being wrong.";' in stripped:
        return indent + 'mes "Por cierto, " + strcharinfo(0) + ", obtuviste - 10 puntos por mentir y por estar equivocado.";\n'
    if 'mes "So, I must give you - 10 points, " + strcharinfo(0) + ".";' in stripped:
        return indent + 'mes "Asi que, debo darte - 10 puntos, " + strcharinfo(0) + ".";\n'
    if 'mes "..." + strcharinfo(0) + ", have you lost your mind?";' in stripped:
        return indent + 'mes "..." + strcharinfo(0) + ", has perdido la cabeza?";\n'

    # mapannounce with strcharinfo
    if 'successfully defeat all the monsters.' in stripped:
        return line.replace('successfully defeat all the monsters.', 'derroto exitosamente a todos los monstruos.')
    if 'Congratulations, ' in stripped and 'You passed the test.' in stripped:
        return line.replace('You passed the test.', 'Aprobaste el examen.')

    # Regular translation
    return translate_line(line)

# Process all lines
new_lines = []
for line in lines:
    new_lines.append(process_line(line))

